```java
// file: src/main/java/com/orderhub/invoice/batch/InvoiceJobConfig.java
package com.orderhub.invoice.batch;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Map;
import javax.sql.DataSource;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.configuration.annotation.StepScope;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.launch.support.RunIdIncrementer;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.database.JdbcBatchItemWriter;
import org.springframework.batch.item.database.JdbcPagingItemReader;
import org.springframework.batch.item.database.Order;
import org.springframework.batch.item.database.builder.JdbcBatchItemWriterBuilder;
import org.springframework.batch.item.database.builder.JdbcPagingItemReaderBuilder;
import org.springframework.batch.item.validator.ValidationException;
import org.springframework.batch.repeat.RepeatStatus;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.dao.TransientDataAccessException;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.PlatformTransactionManager;

@Configuration
public class InvoiceJobConfig {

    @Bean
    @StepScope                                              // created per step execution, can read job parameters
    JdbcPagingItemReader<ShippedOrder> shippedOrdersReader(DataSource dataSource,
            @Value("#{jobParameters['runDate']}") LocalDate runDate) {
        return new JdbcPagingItemReaderBuilder<ShippedOrder>()
                .name("shippedOrdersReader")                // key prefix for its ExecutionContext state
                .dataSource(dataSource)
                .selectClause("select o.id, o.customer_id, o.net_total, c.country")
                .fromClause("from orders o join customers c on c.id = o.customer_id")
                .whereClause("where o.status = 'SHIPPED' and o.shipped_at::date = :runDate "
                        + "and not exists (select 1 from invoice i where i.order_id = o.id)")
                .parameterValues(Map.of("runDate", runDate))
                .sortKeys(Map.of("id", Order.ASCENDING))      // keyset paging: restartable
                .pageSize(500)
                .rowMapper((rs, n) -> new ShippedOrder(rs.getLong(1), rs.getLong(2), rs.getBigDecimal(3), rs.getString(4)))
                .build();
    }

    @Bean
    @StepScope
    ItemProcessor<ShippedOrder, Invoice> invoiceProcessor(@Value("#{jobParameters['runDate']}") LocalDate runDate) {
        Map<String, BigDecimal> vat = Map.of("DE", new BigDecimal("0.19"), "FR", new BigDecimal("0.20"),
                "NL", new BigDecimal("0.21"));
        return order -> {
            if (order.net().signum() == 0) return null;                    // filter: nothing to invoice
            BigDecimal rate = vat.get(order.country());
            if (rate == null) throw new ValidationException("no VAT rate for " + order.country());
            BigDecimal tax = order.net().multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
            return new Invoice(order.id(), order.customerId(), order.net(), tax, order.net().add(tax), runDate);
        };
    }

    @Bean
    JdbcBatchItemWriter<Invoice> invoiceWriter(DataSource dataSource) {
        return new JdbcBatchItemWriterBuilder<Invoice>()
                .dataSource(dataSource)
                .sql("""
                     insert into invoice(order_id, customer_id, net, tax, gross, invoice_date)
                     values (:orderId, :customerId, :net, :tax, :gross, :date)
                     on conflict (order_id) do nothing""")            // idempotent on re-processing
                .beanMapped()                                          // record accessors map to :names
                .build();
    }

    @Bean
    Step createInvoicesStep(JobRepository jobRepository, PlatformTransactionManager tx,
                            JdbcPagingItemReader<ShippedOrder> shippedOrdersReader,
                            ItemProcessor<ShippedOrder, Invoice> invoiceProcessor,
                            JdbcBatchItemWriter<Invoice> invoiceWriter) {
        return new StepBuilder("createInvoices", jobRepository)
                .<ShippedOrder, Invoice>chunk(500, tx)                 // one transaction per 500 items
                .reader(shippedOrdersReader)
                .processor(invoiceProcessor)
                .writer(invoiceWriter)
                .faultTolerant()
                .skip(ValidationException.class).skipLimit(100)
                .retry(TransientDataAccessException.class).retryLimit(3)
                .build();
    }

    @Bean
    Step recordRunStep(JobRepository jobRepository, PlatformTransactionManager tx, JdbcClient jdbc) {
        return new StepBuilder("recordRun", jobRepository)
                .tasklet((contribution, chunkContext) -> {
                    Object runDate = chunkContext.getStepContext().getJobParameters().get("runDate");
                    jdbc.sql("insert into invoice_run(run_date, finished_at) values (cast(? as date), now())")
                        .param(String.valueOf(runDate)).update();
                    return RepeatStatus.FINISHED;
                }, tx)
                .build();
    }

    @Bean
    Job invoiceJob(JobRepository jobRepository, Step createInvoicesStep, Step recordRunStep) {
        return new JobBuilder("invoiceJob", jobRepository)
                .start(createInvoicesStep)
                .next(recordRunStep)
                .build();
    }
}
```

```java
// file: src/main/java/com/orderhub/invoice/batch/InvoiceJobScheduler.java
package com.orderhub.invoice.batch;

import java.time.LocalDate;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.JobParameters;
import org.springframework.batch.core.JobParametersBuilder;
import org.springframework.batch.core.launch.JobLauncher;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class InvoiceJobScheduler {
    private final JobLauncher launcher;
    private final Job invoiceJob;

    public InvoiceJobScheduler(JobLauncher launcher, Job invoiceJob) {
        this.launcher = launcher;
        this.invoiceJob = invoiceJob;
    }

    @Scheduled(cron = "0 30 1 * * *", zone = "Europe/Berlin")      // 01:30 every night
    public void runForYesterday() throws Exception {
        JobParameters params = new JobParametersBuilder()
                .addLocalDate("runDate", LocalDate.now().minusDays(1))   // identifying: one instance per day
                .toJobParameters();
        JobExecution execution = launcher.run(invoiceJob, params);
        System.out.println("invoiceJob " + params.getLocalDate("runDate") + " -> " + execution.getStatus());
    }
}
```

### Walkthrough
- **`spring.batch.job.enabled: false`** stops Boot from running every `Job` bean at startup, which would be surprising in a web application; the scheduler launches it instead. No `@EnableBatchProcessing`, so Boot's auto-configured `JobRepository` and `JobLauncher` are used.
- **`@StepScope` reader** is created lazily per step execution, which allows late binding of `#{jobParameters['runDate']}`. `JdbcPagingItemReader` with a sort key on `id` issues keyset queries (`where ... and id > :lastId order by id limit 500`) and saves the last key in the step's `ExecutionContext` at each commit.
- **Processor:** returning `null` filters an item (counted in `filterCount`); throwing `ValidationException` makes the item skippable because of `.skip(ValidationException.class)`.
- **Writer:** `JdbcBatchItemWriter` sends the whole chunk as a JDBC batch. `on conflict do nothing` makes it idempotent, which matters because chunks may be re-processed after a failure or during skip scanning.
- **Step:** `chunk(500, tx)` means read and process 500 items, write them, then commit together with the `JobRepository` update. Fault tolerance skips up to 100 invalid orders and retries transient database errors three times.
- **Tasklet step** runs once after the chunk step; `RepeatStatus.FINISHED` ends it.
- **Scheduler:** `runDate` is an identifying parameter, so each day is one `JobInstance`. If last night's run failed, launching again with the same date restarts it from the last committed chunk; if it completed, a second launch for the same date is refused.

### Output
```text
INFO  o.s.b.c.l.s.TaskExecutorJobLauncher : Job: [SimpleJob: [name=invoiceJob]] launched with the following parameters: [{'runDate':'{value=2026-11-24, type=class java.time.LocalDate, identifying=true}'}]
INFO  o.s.batch.core.job.SimpleStepHandler : Executing step: [createInvoices]
INFO  o.s.batch.core.step.AbstractStep : Step: [createInvoices] executed in 41s210ms
INFO  o.s.batch.core.job.SimpleStepHandler : Executing step: [recordRun]
INFO  o.s.batch.core.step.AbstractStep : Step: [recordRun] executed in 12ms
INFO  o.s.b.c.l.s.TaskExecutorJobLauncher : Job: [SimpleJob: [name=invoiceJob]] completed with the following parameters: [{'runDate':'{value=2026-11-24, type=class java.time.LocalDate, identifying=true}'}] and the following status: [COMPLETED] in 41s301ms
invoiceJob 2026-11-24 -> COMPLETED
```
Metadata after the run:
```sql
SELECT step_name, read_count, filter_count, write_count, process_skip_count, commit_count, status
FROM batch_step_execution WHERE job_execution_id = 57;
--  step_name      | read_count | filter_count | write_count | process_skip_count | commit_count | status
-- ----------------+------------+--------------+-------------+--------------------+--------------+-----------
--  createInvoices |     184212 |           31 |      184178 |                  3 |          369 | COMPLETED
--  recordRun      |          0 |            0 |           0 |                  0 |            1 | COMPLETED
```
184,212 read, 31 filtered (zero net), 3 skipped (missing VAT rate), 184,178 written in 369 commits (368 full chunks plus a partial one).

### Compare
| Approach | Restart after failure | Skip and retry | Memory | Audit trail |
|---|---|---|---|---|
| `@Scheduled` method with a loop | Manual | Manual | Your responsibility | Logs only |
| `@Scheduled` plus `TransactionTemplate` chunks | Manual position tracking | Manual | Bounded | Logs |
| Spring Batch chunk step | Built in from last commit | Declarative | Bounded by chunk size | `BATCH_*` tables, metrics |
| SQL-only (`INSERT ... SELECT`) | Rerun whole statement | No | Database side | None |
| Stream processing (Kafka Streams) | Offsets | Custom | Bounded | Topic offsets |

## 4. Interview Questions
**Basic**
1. **What is Spring Batch used for?**
   Large, non-interactive data processing: imports, exports, nightly calculations, migrations. It provides chunked transactions, restartability, skip and retry, and job metadata, so long jobs survive failures without reprocessing or losing data.
2. **Explain chunk-oriented processing.**
   A step reads items one at a time with an `ItemReader`, optionally transforms each with an `ItemProcessor`, collects them into a chunk of N, writes the chunk with an `ItemWriter`, and commits the transaction together with progress metadata. It repeats until the reader returns null.
3. **What is the difference between a `JobInstance` and a `JobExecution`?**
   A `JobInstance` is a logical run identified by job name plus identifying parameters (for example `runDate=2026-11-24`). A `JobExecution` is one attempt to run it; a failed instance can have several executions until one completes.

**Follow-up**
4. **How does Spring Batch restart a failed job from where it stopped?**
   At each chunk commit it stores step counts and the reader's state (`ExecutionContext`) in the `JobRepository` within the same transaction. Relaunching with the same identifying parameters creates a new execution of the same instance, and restartable readers reposition from the saved state.
5. **What happens when you add `@EnableBatchProcessing` in a Boot 3 application?**
   It turns off Spring Boot's batch auto-configuration (job launching at startup, schema initialization, property-based configuration), so you must configure the infrastructure yourself. In Boot 3 it is not needed; just define `Job` beans.
6. **How do skip and retry work in a fault-tolerant step?**
   Retry re-attempts an item or chunk on listed transient exceptions up to a limit. Skip lets listed exceptions be ignored for an item up to a skip limit; when a write fails, the chunk is rolled back and items are written one by one to identify the bad one. Skipped items can be logged with a `SkipListener`.

**Tricky / scenario**
7. **A job processing 10 million rows with `JpaItemWriter` slows down over time and finally runs out of memory. Why, and what do you change?**
   Possibly entities accumulate in a persistence context that is not cleared between chunks (custom writers using a shared `EntityManager`), or the reader is a non-paging JPA query loading too much. Use paging or cursor readers, `JdbcBatchItemWriter` for plain inserts, verify JDBC batching, and keep chunk sizes moderate (100 to 1000).
8. **The nightly job runs on 3 instances of the service and invoices get created three times. How do you prevent it?**
   With identifying parameters, the `JobRepository` prevents two executions of the same instance (concurrent launches fail with `JobExecutionAlreadyRunningException` thanks to database locking), as long as all instances share the same metadata database. Additionally, make the writer idempotent (unique constraint plus `on conflict do nothing`) and consider a scheduler lock (ShedLock) or running batch in a separate deployment.
9. **How would you make a 2-hour job finish in 20 minutes?**
   Measure first: often the writer lacks batching or the processor does per-item remote calls. Then parallelise: partition by ID ranges or dates with a partitioned step and a `TaskExecutor`, use thread-safe paging readers, and size the connection pool for the number of workers. Remote partitioning across instances for even larger volumes.

**What the interviewer is really testing:** whether you can design a restartable, idempotent bulk job and know what Spring Batch automates versus a hand-written loop.

## 5. Pitfalls & Best Practices
### Common mistakes
| Mistake | What goes wrong | Fix |
|---|---|---|
| Leaving `spring.batch.job.enabled=true` in a web app | Jobs run on every startup of every instance | Disable and launch explicitly |
| Adding `@EnableBatchProcessing` in Boot 3 | Boot batch auto-configuration disappears | Remove it |
| Non-idempotent writer | Duplicates after restarts or skip scanning | Unique constraints and upserts |
| Non-identifying or random parameters for daily jobs | Same day can run twice, restart impossible | Business key (date) as identifying parameter |
| Cursor reader in a multi-threaded step | Corrupted reads, not thread-safe | Paging reader or synchronized wrapper |
| Huge chunk size | Long transactions, big rollbacks, memory | 100 to 1000, measure |

### Best practices
- Keep the `JobRepository` in a durable shared database and manage its schema with Flyway.
- Make every step restartable and every writer idempotent; test restart by killing the job mid-run.
- Expose metrics (Spring Batch publishes Micrometer timers like `spring.batch.job` and `spring.batch.step`) and alert on failed executions.
- Run heavy batch jobs in a separate deployment (or Kubernetes `CronJob`) so they do not compete with user traffic for pools and CPU.
- Use a read replica for reading when the job tolerates lag, and the primary for writing.

### Compare with
| Tool | Strength |
|---|---|
| Spring Batch | Restartable chunked jobs in Java with rich readers and writers |
| `@Scheduled` plus plain code | Small, quick periodic tasks |
| Database jobs (pg_cron, stored procedures) | Pure SQL transformations near the data |
| Kafka Streams or Flink | Continuous streaming instead of nightly batches |
| Apache Spark | Distributed processing of very large datasets |

## 6. Hands-on Exercise
Add a second job to OrderHub: `stockImportJob` reading `stock-YYYY-MM-DD.csv` (`sku,on_hand`) with `FlatFileItemReader`, upserting into `stock` with `JdbcBatchItemWriter` in chunks of 1,000, skipping lines with a non-numeric quantity (up to 50) and logging each skipped line. Acceptance criteria: the file path is a job parameter; the job is restartable after a crash at line 400,000; skipped lines are logged with their line number; a test with a 10-line file containing 2 bad lines asserts `writeCount = 8` and `skipCount = 2`.

<details><summary>Solution</summary>

```java
// file: src/main/java/com/orderhub/inventory/batch/StockImportJobConfig.java
package com.orderhub.inventory.batch;

import javax.sql.DataSource;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.SkipListener;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.configuration.annotation.StepScope;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.database.JdbcBatchItemWriter;
import org.springframework.batch.item.database.builder.JdbcBatchItemWriterBuilder;
import org.springframework.batch.item.file.FlatFileItemReader;
import org.springframework.batch.item.file.FlatFileParseException;
import org.springframework.batch.item.file.builder.FlatFileItemReaderBuilder;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.FileSystemResource;
import org.springframework.transaction.PlatformTransactionManager;

@Configuration
public class StockImportJobConfig {
    private static final Logger log = LoggerFactory.getLogger(StockImportJobConfig.class);

    public record StockLine(String sku, int onHand) { }

    @Bean
    @StepScope
    FlatFileItemReader<StockLine> stockReader(@Value("#{jobParameters['file']}") String file) {
        return new FlatFileItemReaderBuilder<StockLine>()
                .name("stockReader")                        // saves the current line count for restarts
                .resource(new FileSystemResource(file))
                .linesToSkip(1)
                .delimited().names("sku", "onHand")
                .fieldSetMapper(fs -> new StockLine(fs.readString("sku"), fs.readInt("onHand")))  // throws on bad int
                .build();
    }

    @Bean
    JdbcBatchItemWriter<StockLine> stockWriter(DataSource dataSource) {
        return new JdbcBatchItemWriterBuilder<StockLine>()
                .dataSource(dataSource)
                .sql("""
                     insert into stock(sku, on_hand, updated_at) values (:sku, :onHand, now())
                     on conflict (sku) do update set on_hand = excluded.on_hand, updated_at = now()""")
                .beanMapped()
                .build();
    }

    @Bean
    Step importStock(JobRepository repo, PlatformTransactionManager tx,
                     FlatFileItemReader<StockLine> stockReader, JdbcBatchItemWriter<StockLine> stockWriter) {
        return new StepBuilder("importStock", repo)
                .<StockLine, StockLine>chunk(1000, tx)
                .reader(stockReader)
                .writer(stockWriter)
                .faultTolerant()
                .skip(FlatFileParseException.class).skipLimit(50)
                .listener(new SkipListener<StockLine, StockLine>() {
                    @Override
                    public void onSkipInRead(Throwable t) {
                        if (t instanceof FlatFileParseException e) {
                            log.warn("skipped line {}: '{}'", e.getLineNumber(), e.getInput());
                        }
                    }
                })
                .build();
    }

    @Bean
    Job stockImportJob(JobRepository repo, Step importStock) {
        return new JobBuilder("stockImportJob", repo).start(importStock).build();
    }
}
```

```java
// file: src/test/java/com/orderhub/inventory/batch/StockImportJobIT.java (essential part)
@SpringBatchTest
@SpringBootTest(properties = "spring.batch.job.enabled=false")
@Import(TestcontainersConfig.class)
class StockImportJobIT {
    @Autowired JobLauncherTestUtils jobs;

    @Test
    void skipsBadLines(@TempDir Path dir) throws Exception {
        Path csv = dir.resolve("stock-2026-11-24.csv");
        Files.writeString(csv, """
                sku,on_hand
                A,1
                B,2
                C,x
                D,4
                E,5
                F,
                G,7
                H,8
                I,9
                J,10
                """);
        JobExecution exec = jobs.launchJob(new JobParametersBuilder()
                .addString("file", csv.toString()).toJobParameters());
        StepExecution step = exec.getStepExecutions().iterator().next();
        assertThat(exec.getStatus()).isEqualTo(BatchStatus.COMPLETED);
        assertThat(step.getWriteCount()).isEqualTo(8);
        assertThat(step.getSkipCount()).isEqualTo(2);
    }
}
```
Log:
```text
WARN  StockImportJobConfig : skipped line 4: 'C,x'
WARN  StockImportJobConfig : skipped line 7: 'F,'
```
The reader's `name` makes it store `stockReader.read.count` in the step `ExecutionContext` at each commit; on restart it skips that many lines. `@SpringBatchTest` with one `Job` bean in the test context autowires it into `JobLauncherTestUtils` (with two jobs, set the job explicitly).
</details>

## 7. Recall
Q: What are the three parts of a Spring Batch chunk-oriented step?
A: An `ItemReader`, an optional `ItemProcessor`, and an `ItemWriter` that writes a chunk per transaction.

Q: How does Spring Batch restart a failed job from the last committed chunk?
A: The `JobRepository` stores step progress and reader state in the `ExecutionContext` at each commit; relaunching with the same identifying parameters resumes from it.

Q: What identifies a Spring Batch JobInstance?
A: The job name plus its identifying `JobParameters`.

Q: What happens if you add @EnableBatchProcessing in a Spring Boot 3 application?
A: Boot's batch auto-configuration backs off, so you must configure the batch infrastructure yourself.

Q: Why should Spring Batch item writers be idempotent?
A: Chunks may be re-processed after failures, restarts or skip scanning, so writes must not create duplicates.

Q: In a Spring Batch ItemProcessor, what does returning null do?
A: It filters the item out: it is not passed to the writer and is counted as filtered.

**Related:** [[Batch Inserts and Updates]] · [[Multiple Datasources and Read Replicas]] · [[How @Transactional Really Works]]

# Coding drill: Data performance scenarios

Ten scenarios that mirror real production incidents. For each, state the root cause aloud first, then write the fix. Interviewers care as much about how you diagnose (which metric, which log, which plan) as about the code.

## 1. Fix the N+1 on the orders list
`GET /api/orders?customerId=42` logs 1 + 2N SQL statements.

```java
// Spring snippet: org.springframework imports omitted for brevity
@Transactional(readOnly = true)
public List<OrderDto> list(long customerId) {
    return orders.findByCustomerId(customerId).stream()
        .map(o -> new OrderDto(o.getId(), o.getCustomer().getName(),
                o.getLines().stream().mapToInt(OrderLine::getQuantity).sum()))
        .toList();
}
```
Hint: two lazy associations are touched per order.

<details><summary>Solution</summary>

Each order lazily loads its customer and its lines. Fetch them up front, or project to a DTO with an aggregate:

```java
// Spring snippet: org.springframework imports omitted for brevity
public interface OrderRepository extends JpaRepository<Order, Long> {

    // Option A: entity graph for both associations (one query with joins)
    @EntityGraph(attributePaths = { "customer", "lines" })
    List<Order> findByCustomerId(long customerId);

    // Option B (better for lists): DTO projection with aggregation in SQL
    @Query("""
           select new com.orderhub.order.OrderDto(o.id, c.name, coalesce(sum(l.quantity), 0))
           from Order o join o.customer c left join o.lines l
           where c.id = :customerId
           group by o.id, c.name""")
    List<OrderDto> summaries(@Param("customerId") long customerId);
}
```
Option B returns exactly the needed columns in one query and avoids loading lines at all. Fetching a collection with an entity graph and paginating at the same time makes Hibernate paginate in memory (warning HHH90003004), another reason to prefer the projection for lists. Lock the fix in with a test asserting the statement count.
</details>

## 2. Pool exhaustion caused by a remote call
Under load: "Connection is not available, request timed out after 3000ms (total=10, active=10, idle=0, waiting=40)". Database CPU is 10 percent.

```java
// Spring snippet: org.springframework imports omitted for brevity
@Transactional
public Payment pay(long orderId) {
    Order order = orders.findById(orderId).orElseThrow();
    PaymentResult result = paymentGateway.charge(order.getTotal());   // 1-3 s HTTP call
    order.markPaid(result.reference());
    return payments.save(new Payment(orderId, result.reference()));
}
```
Hint: what does the connection do during `charge`?

<details><summary>Solution</summary>

The transaction holds a connection for the whole HTTP call; 10 connections serve at most 3 to 10 payments per second. Split the work so the remote call happens outside any transaction:

```java
// Spring snippet: org.springframework imports omitted for brevity
@Service
public class PaymentFacade {
    private final OrderQueries queries;          // read-only, short transaction
    private final PaymentGateway gateway;
    private final PaymentRecorder recorder;      // separate bean, short write transaction

    public PaymentFacade(OrderQueries queries, PaymentGateway gateway, PaymentRecorder recorder) {
        this.queries = queries;
        this.gateway = gateway;
        this.recorder = recorder;
    }

    public Payment pay(long orderId) {           // no @Transactional here
        BigDecimal total = queries.totalOf(orderId);
        PaymentResult result = gateway.charge(total);
        return recorder.record(orderId, result.reference());
    }
}

@Service
class PaymentRecorder {
    private final OrderRepository orders;
    private final PaymentRepository payments;
    PaymentRecorder(OrderRepository orders, PaymentRepository payments) { this.orders = orders; this.payments = payments; }

    @Transactional
    public Payment record(long orderId, String reference) {
        orders.findById(orderId).orElseThrow().markPaid(reference);
        return payments.save(new Payment(orderId, reference));
    }
}
```
Connection hold time drops from seconds to milliseconds. Because the charge and the record are no longer atomic, protect against a crash in between with an idempotency key at the gateway and a reconciliation job (or the outbox pattern from Phase 20).
</details>

## 3. Design the index for a query
```sql
SELECT id, total, created_at FROM orders
WHERE tenant_id = ? AND status IN ('NEW', 'PAID') AND created_at >= ?
ORDER BY created_at DESC
LIMIT 50;
```
`orders` has 80 million rows; 5 percent are NEW or PAID. Write the index and justify it.

Hint: equality first; consider a partial index.

<details><summary>Solution</summary>

```sql
CREATE INDEX CONCURRENTLY idx_orders_tenant_open_created
    ON orders (tenant_id, created_at DESC)
    INCLUDE (total)
    WHERE status IN ('NEW', 'PAID');
```
- `tenant_id` is the equality column, so it leads.
- `created_at DESC` serves both the range filter and the `ORDER BY`, so the database reads the first 50 matching entries and stops, with no sort.
- The partial predicate matches the query's `status IN (...)` exactly, so the index contains only 5 percent of rows: small, hot in memory, cheap to maintain.
- `INCLUDE (total)` lets the query be answered mostly from the index (add `id` too for a pure index-only scan).
The query must use the same status predicate for PostgreSQL to choose a partial index.
</details>

## 4. Make the import fast
Importing 200,000 customers takes 4 minutes.

```java
// Spring snippet: org.springframework imports omitted for brevity
@Entity
public class Customer {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String email;
}

@Transactional
public void importAll(List<CustomerRow> rows) {
    rows.forEach(r -> customerRepository.save(new Customer(r.email())));
}
```
Hint: three separate problems.

<details><summary>Solution</summary>

Problems: IDENTITY disables insert batching; no `batch_size` configured; the persistence context grows to 200,000 entities.

```java
// Spring snippet: org.springframework imports omitted for brevity
@Entity
public class Customer {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "customer_seq")
    @SequenceGenerator(name = "customer_seq", sequenceName = "customer_seq", allocationSize = 50)
    private Long id;
    private String email;
}

@Transactional
public void importAll(List<CustomerRow> rows) {
    for (int i = 0; i < rows.size(); i++) {
        em.persist(new Customer(rows.get(i).email()));
        if ((i + 1) % 50 == 0) { em.flush(); em.clear(); }
    }
}
```
```yaml
spring:
  jpa:
    properties:
      hibernate:
        jdbc.batch_size: 50
        order_inserts: true
  datasource:
    hikari:
      data-source-properties:
        reWriteBatchedInserts: true
```
```sql
CREATE SEQUENCE customer_seq INCREMENT BY 50;
```
Typical result: from about 4 minutes to under 10 seconds. If the table already has an identity column in production, migrate the default to the sequence or use `JdbcTemplate.batchUpdate` for imports.
</details>

## 5. Cache the product page correctly
Add caching to `findProduct(id)` so that (a) price changes are visible on all 6 instances immediately, (b) nonexistent IDs do not hammer the database, and (c) a Redis outage does not break the page.

Hint: shared cache, negative caching with a short TTL, error handler.

<details><summary>Solution</summary>

```java
// Spring snippet: org.springframework imports omitted for brevity
@Service
public class ProductPageService {
    private final ProductRepository products;
    public ProductPageService(ProductRepository products) { this.products = products; }

    @Cacheable(cacheNames = "productPage", key = "#id")
    @Transactional(readOnly = true)
    public Optional<ProductView> findProduct(long id) {           // Optional.empty() is cached too
        return products.findById(id).map(ProductView::from);
    }

    @CacheEvict(cacheNames = "productPage", key = "#id")
    @Transactional
    public void changePrice(long id, BigDecimal price) {
        products.findById(id).orElseThrow().changePrice(price);
    }
}

@Configuration
@EnableCaching
class ProductPageCacheConfig implements CachingConfigurer {
    @Bean
    RedisCacheManagerBuilderCustomizer productPageTtl() {
        return b -> b.withCacheConfiguration("productPage",
                RedisCacheConfiguration.defaultCacheConfig()
                        .entryTtl(Duration.ofMinutes(15))
                        .serializeValuesWith(SerializationPair.fromSerializer(new GenericJackson2JsonRedisSerializer())))
                .transactionAware();
    }

    @Override
    public CacheErrorHandler errorHandler() {
        return new SimpleCacheErrorHandler() {
            @Override public void handleCacheGetError(RuntimeException e, Cache c, Object k) { /* treat as miss */ }
            @Override public void handleCachePutError(RuntimeException e, Cache c, Object k, Object v) { }
        };
    }
}
```
Redis is shared, so one eviction is seen by every instance (a). Spring unwraps `Optional`: an empty result is stored as a null value, so the cache must allow nulls (the default `RedisCacheConfiguration` does); for (b) use a separate short-TTL configuration for misses if 15 minutes is too long. The error handler makes Redis failures behave like misses (c), and `transactionAware()` evicts only after the price change commits.
</details>

## 6. Replace offset pagination
The mobile app's infinite scroll uses `PageRequest.of(page, 20)` on `orders` ordered by `createdAt desc`; page 2,000 takes 3 seconds. Rewrite the repository method and the API contract.

Hint: return a cursor.

<details><summary>Solution</summary>

```java
// Spring snippet: org.springframework imports omitted for brevity
public interface OrderFeedRepository extends Repository<Order, Long> {
    @Query("""
           select new com.orderhub.order.OrderSummary(o.id, o.status, o.total, o.createdAt)
           from Order o
           where o.customer.id = :customerId
             and (o.createdAt < :cursorTime or (o.createdAt = :cursorTime and o.id < :cursorId))
           order by o.createdAt desc, o.id desc""")
    List<OrderSummary> after(@Param("customerId") long customerId, @Param("cursorTime") Instant cursorTime,
                             @Param("cursorId") long cursorId, Limit limit);
}

public record FeedPage(List<OrderSummary> items, String nextCursor) { }

public FeedPage feed(long customerId, String cursor) {
    Instant time = Instant.MAX;
    long id = Long.MAX_VALUE;
    if (cursor != null) {
        String[] parts = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8).split("_");
        time = Instant.parse(parts[0]);
        id = Long.parseLong(parts[1]);
    }
    List<OrderSummary> items = repo.after(customerId, time, id, Limit.of(20));
    String next = items.size() < 20 ? null : Base64.getUrlEncoder().encodeToString(
            (items.get(19).createdAt() + "_" + items.get(19).id()).getBytes(StandardCharsets.UTF_8));
    return new FeedPage(items, next);
}
```
With an index on `(customer_id, created_at DESC, id DESC)` every page is an index seek, so page 2,000 costs the same as page 1. The opaque cursor hides the implementation from clients. `Instant.MAX` is beyond what PostgreSQL timestamps can store, so in practice start from `Instant.now().plusSeconds(60)` or omit the condition on the first page.
</details>

## 7. Read your own writes with a replica
After placing an order, the confirmation page sometimes shows "order not found". Reads use `@Transactional(readOnly = true)` routed to a replica. Fix it without sending all reads to the primary.

Hint: which read must see the write?

<details><summary>Solution</summary>

```java
// Spring snippet: org.springframework imports omitted for brevity
@Service
public class OrderQueryService {
    private final OrderRepository orders;
    public OrderQueryService(OrderRepository orders) { this.orders = orders; }

    @Transactional(readOnly = true)                      // replica: tolerant reads
    public Optional<OrderView> find(long id) {
        return orders.findById(id).map(OrderView::from);
    }

    @Transactional                                       // primary: must see the latest commit
    public Optional<OrderView> findFresh(long id) {
        return orders.findById(id).map(OrderView::from);
    }

}

@Service
public class OrderConfirmationService {
    private final OrderQueryService queries;             // another bean: calls go through its proxy
    public OrderConfirmationService(OrderQueryService queries) { this.queries = queries; }

    public OrderView findWithFallback(long id) {
        return queries.find(id).or(() -> queries.findFresh(id))   // replica first, primary if lagging
                .orElseThrow(() -> new OrderNotFoundException(id));
    }
}
```
The confirmation page calls `findWithFallback`, which costs one extra primary read only in the lag case. The fallback lives in a separate bean on purpose: if it called `find` and `findFresh` on `this`, the proxy would be bypassed and both would run with no transaction attributes (so no read-only routing). For a broader fix, pin users to the primary for a few seconds after a write (see the read replicas topic).
</details>

## 8. Distributed rate limiter with Redis
Limit each API key to 100 requests per minute across all OrderHub instances. Write the Redis logic so the increment and expiry are atomic.

Hint: Lua script or `INCR` plus conditional `EXPIRE` inside one script.

<details><summary>Solution</summary>

```java
// Spring snippet: org.springframework imports omitted for brevity
@Component
public class ApiRateLimiter {
    private static final DefaultRedisScript<Long> INCR_WITH_TTL = new DefaultRedisScript<>("""
            local current = redis.call('INCR', KEYS[1])
            if current == 1 then
              redis.call('PEXPIRE', KEYS[1], ARGV[1])
            end
            return current""", Long.class);

    private final StringRedisTemplate redis;
    public ApiRateLimiter(StringRedisTemplate redis) { this.redis = redis; }

    public boolean allow(String apiKey, int limitPerMinute) {
        long window = System.currentTimeMillis() / 60_000;
        String key = "orderhub:rate:" + apiKey + ":" + window;
        Long count = redis.execute(INCR_WITH_TTL, List.of(key), "60000");
        return count != null && count <= limitPerMinute;
    }
}
```
The Lua script runs atomically inside Redis, so there is no gap where the key exists without a TTL. This is a fixed-window limiter (bursts of up to 200 across a window boundary are possible); a sliding window uses a sorted set of timestamps, and Spring Cloud Gateway's `RedisRateLimiter` implements a token bucket.
</details>

## 9. The stale entity after a bulk update
```java
// Spring snippet: org.springframework imports omitted for brevity
@Transactional
public BigDecimal applyDiscount(String category) {
    Product p = products.findById(7L).orElseThrow();       // category = "kitchen", price 10.00
    products.discountCategory(category, new BigDecimal("0.9")); // @Modifying update query
    return products.findById(7L).orElseThrow().getPrice();
}
```
It returns 10.00, but the database says 9.00. Why? Fix it.

Hint: where does the second `findById` get the entity from?

<details><summary>Solution</summary>

The bulk JPQL update runs directly in the database and bypasses the persistence context. The second `findById` returns the already managed entity from the first-level cache with the old price.

```java
// Spring snippet: org.springframework imports omitted for brevity
@Modifying(flushAutomatically = true, clearAutomatically = true)
@Query("update Product p set p.price = p.price * :factor where p.category = :category")
int discountCategory(@Param("category") String category, @Param("factor") BigDecimal factor);
```
`clearAutomatically` detaches all managed entities after the update, so the next `findById` reloads 9.00; `flushAutomatically` makes sure pending changes are written before the bulk statement. Note that clearing also discards unflushed changes of other entities if flushing is off, which is why both flags go together. If the entity is in the Hibernate second-level cache, the bulk update also evicts its region.
</details>

## 10. Restartable nightly export
Write the core of a job that exports yesterday's orders to `orders-YYYY-MM-DD.csv`, commits every 1,000 rows, and, after a crash at row 600,000, resumes without duplicating lines.

Hint: Spring Batch's file writer is restartable when it knows the position.

<details><summary>Solution</summary>

```java
// Spring snippet: org.springframework imports omitted for brevity
@Bean
@StepScope
JdbcPagingItemReader<OrderCsv> exportReader(DataSource ds, @Value("#{jobParameters['day']}") LocalDate day) {
    return new JdbcPagingItemReaderBuilder<OrderCsv>()
            .name("exportReader")
            .dataSource(ds)
            .selectClause("select id, customer_email, total, created_at")
            .fromClause("from orders")
            .whereClause("where created_at >= :from and created_at < :to")
            .parameterValues(Map.of("from", day.atStartOfDay(), "to", day.plusDays(1).atStartOfDay()))
            .sortKeys(Map.of("id", Order.ASCENDING))
            .pageSize(1000)
            .rowMapper((rs, n) -> new OrderCsv(rs.getLong(1), rs.getString(2), rs.getBigDecimal(3),
                    rs.getTimestamp(4).toInstant()))
            .build();
}

@Bean
@StepScope
FlatFileItemWriter<OrderCsv> exportWriter(@Value("#{jobParameters['day']}") LocalDate day) {
    return new FlatFileItemWriterBuilder<OrderCsv>()
            .name("exportWriter")                         // saves the file position in the ExecutionContext
            .resource(new FileSystemResource("/exports/orders-" + day + ".csv"))
            .headerCallback(w -> w.write("id,customer,total,created_at"))
            .delimited().names("id", "customer", "total", "createdAt")
            .transactional(true)                          // buffer until commit (default)
            .build();
}

@Bean
Step exportStep(JobRepository repo, PlatformTransactionManager tx,
                JdbcPagingItemReader<OrderCsv> exportReader, FlatFileItemWriter<OrderCsv> exportWriter) {
    return new StepBuilder("exportOrders", repo)
            .<OrderCsv, OrderCsv>chunk(1000, tx)
            .reader(exportReader)
            .writer(exportWriter)
            .build();
}
```
At each commit Spring Batch stores the reader's last `id` and the writer's byte position. On restart the writer truncates the file to the last committed position and the reader resumes after the last committed key, so rows 600,001 onwards are written exactly once. Launch with `day` as an identifying parameter so the restart targets the same `JobInstance`.
</details>

# Monolith vs Microservices

**Level: Advanced | Phase 20 | Priority: MUST | Since: architecture style (term popularized around 2014)**

> **30-second interview answer:** A monolith is one deployable unit containing all features; microservices are many small, independently deployable services, each owning one business capability and its own data. Microservices buy independent deployment, independent scaling and team autonomy, and they pay for it with network failures, eventual consistency, distributed debugging and much more operational work. I start with a well-structured modular monolith and extract a service only when a concrete pressure (team size, scaling profile, release cadence, fault isolation) justifies the cost.

## 1. Concept in Simple Words
### Analogy
One big department store versus a street of small specialist shops.

| Shops | Software |
|---|---|
| One department store under one roof | Monolith: one deployable, one process |
| Departments inside the store (shoes, toys) | Modules inside a modular monolith |
| A street of independent shops, each with its own owner and stockroom | Microservices, each with its own team and database |
| Walking between departments indoors: instant, never rains | In-process method call: nanoseconds, never fails on its own |
| Crossing the street between shops: traffic, rain, a shop may be closed | Network call: latency, timeouts, the other service may be down |
| Renovating one shop without closing the street | Deploying one service independently |
| A street needs roads, signs, a map and traffic lights | Gateway, discovery, config, monitoring, CI/CD per service |

### What it is
- **Monolith:** the whole application is built, tested and deployed as one artifact (one JAR) and runs as one process. It usually shares one database.
- **Modular monolith:** still one deployable, but internally split into modules with strict boundaries (each module exposes a small public API, hides its internals, and owns its tables). Spring Modulith (`spring-modulith`) can verify these boundaries in tests.
- **Microservices:** an architecture where the system is a set of services that are independently deployable, organized around business capabilities, own their data (no shared database), and communicate over the network (HTTP or messaging).
- **Distributed monolith:** the worst of both: many services that must be deployed together because they share a database or call each other synchronously in long chains.

### Why it exists
As a monolith grows to dozens of developers, everyone steps on each other: one release train, one huge test suite, one technology stack, and a bug in the reporting code can take down checkout. Microservices appeared at companies like Amazon and Netflix to let hundreds of small teams ship independently. The catch is that they move complexity from the code into the network and the operations. Without a real organizational or scaling need, that complexity is pure cost.

## 2. How It Works
The key difference is what a "call" means.

```text
MONOLITH                                   MICROSERVICES
OrderService.place()                       order-service.place()
   |  in-process call (~100 ns)               |  HTTP over network (1 to 50 ms)
   v                                          v
InventoryService.reserve()                 inventory-service /reserve
   |                                          |   can time out, be slow, be down,
   v                                          |   succeed but the response is lost
one DB transaction: order + stock          two databases: no single ACID transaction
COMMIT or ROLLBACK together                needs a saga with compensation
```

Availability multiplies along a synchronous chain. If each service is up 99.9% of the time and a request touches five services in a row, the request succeeds only 0.999 to the power 5, about 99.5% of the time: five times more downtime than one service.

```mermaid
flowchart LR
    A["Need to split?"] --> B{"More than 2 or 3 teams on one codebase?"}
    B -- "no" --> M["Stay modular monolith"]
    B -- "yes" --> C{"Clear bounded contexts with little chatty traffic?"}
    C -- "no" --> M
    C -- "yes" --> D{"Platform ready: CI/CD, monitoring, tracing, on-call?"}
    D -- "no" --> P["Build the platform first"]
    D -- "yes" --> S["Extract one service (strangler fig)"]
```

**Strangler fig pattern:** extract one capability at a time. Put a gateway in front of the monolith, route one path (say `/api/notifications/**`) to the new service, keep the rest going to the monolith, and repeat. You never do a big-bang rewrite.

## 3. Code Example
### Code
A plain Java 21 program that quantifies the two hidden costs every interviewer wants you to mention: availability that multiplies across a call chain, and latency that adds up per hop.

```java
import java.util.List;

public class DistributionCost {

    record Hop(String name, double availability, double latencyMs) { }

    // Probability that ALL hops succeed when they are called one after another
    static double chainAvailability(List<Hop> hops) {
        double result = 1.0;
        for (Hop h : hops) result *= h.availability();
        return result;
    }

    static double chainLatency(List<Hop> hops) {
        return hops.stream().mapToDouble(Hop::latencyMs).sum();
    }

    public static void main(String[] args) {
        int[] chainLengths = {1, 3, 5, 10, 20};
        double minutesPerMonth = 30 * 24 * 60;          // 43,200 minutes

        System.out.println("services  availability  downtime/month");
        for (int n : chainLengths) {
            double a = Math.pow(0.999, n);              // each service: 99.9 percent
            double downtime = (1 - a) * minutesPerMonth;
            System.out.println(String.format("%8d  %11.2f%%  %10.1f min", n, a * 100, downtime));
        }

        // One checkout request in OrderHub after the split
        List<Hop> checkout = List.of(
                new Hop("gateway", 0.9995, 2.0),
                new Hop("order-service", 0.999, 15.0),
                new Hop("inventory-service", 0.999, 12.0),
                new Hop("payment-provider", 0.998, 120.0));

        System.out.println();
        System.out.println(String.format("checkout availability: %.3f%%", chainAvailability(checkout) * 100));
        System.out.println(String.format("checkout latency: %.1f ms (monolith in-process calls: about 0 ms)", chainLatency(checkout)));
    }
}
```

The same split in Spring code. In the monolith, placing an order is one local transaction:

```java
// MONOLITH: one process, one database, one transaction
package com.orderhub.order;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.orderhub.inventory.InventoryService;   // another module, same JVM

@Service
public class OrderService {
    private final OrderRepository orders;
    private final InventoryService inventory;

    public OrderService(OrderRepository orders, InventoryService inventory) {
        this.orders = orders;
        this.inventory = inventory;
    }

    @Transactional                                   // order row + stock rows commit together
    public Order place(PlaceOrderCommand cmd) {
        inventory.reserve(cmd.productId(), cmd.quantity());   // throws -> whole tx rolls back
        return orders.save(Order.newOrder(cmd));
    }
}
```

After the split, the same method crosses the network and loses the shared transaction:

```java
// MICROSERVICES: order-service calls inventory-service over HTTP
package com.orderhub.order;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {
    private final OrderRepository orders;
    private final InventoryClient inventory;         // HTTP client (topic: OpenFeign and HTTP Interfaces)

    public OrderService(OrderRepository orders, InventoryClient inventory) {
        this.orders = orders;
        this.inventory = inventory;
    }

    @Transactional                                   // covers ONLY the orders database
    public Order place(PlaceOrderCommand cmd) {
        // Network call: may time out AFTER inventory already reserved the stock.
        // If the save below fails, the reservation is NOT rolled back automatically.
        inventory.reserve(new ReserveRequest(cmd.productId(), cmd.quantity()));
        return orders.save(Order.newOrder(cmd));
    }
}
```

### Walkthrough
- `chainAvailability` multiplies probabilities because every hop must succeed for the request to succeed. This is why long synchronous chains are dangerous.
- The table shows how downtime grows from 43 minutes a month for one service to over 14 hours for a 20-service chain, even though every individual service meets its 99.9% target.
- `checkout` models a realistic request: the external payment provider dominates latency, and the chain availability drops below the weakest hop.
- The monolith `OrderService` relies on one `@Transactional` boundary: if `save` fails, the stock reservation in the same database rolls back too.
- In the microservice version `@Transactional` only covers the order database. A timeout does not mean the reservation failed, so you need idempotent requests, compensation (a saga) and resilience patterns. That is the whole rest of this phase.

### Output
```text
services  availability  downtime/month
       1        99.90%        43.2 min
       3        99.70%       129.5 min
       5        99.50%       215.6 min
      10        99.00%       430.1 min
      20        98.02%       855.8 min

checkout availability: 99.551%
checkout latency: 149.0 ms (monolith in-process calls: about 0 ms)
```

### Compare
| Aspect | Monolith (modular) | Microservices |
|---|---|---|
| Deployment | One artifact, one pipeline | One pipeline per service |
| Data consistency | ACID transactions | Eventual consistency, sagas |
| Calls between parts | Method calls, compile-time checked | Network calls, versioned contracts |
| Scaling | Scale the whole app | Scale hot services only |
| Failure isolation | One memory leak kills everything | A failing service can be isolated (with circuit breakers) |
| Debugging | One log, one stack trace | Distributed tracing needed |
| Team autonomy | Shared release train | Teams release independently |
| Best for | Small to medium teams, new products | Many teams, mature domain, strong platform |

## 4. Interview Questions
**Basic**
1. **What is a microservice?**
   A small service that owns one business capability and its own data, is deployed independently, and talks to others only through APIs or events. "Small" is about scope and team ownership, not lines of code.
2. **What are the advantages of microservices?**
   Independent deployment and release cadence, independent scaling of hot paths, fault isolation, freedom to pick technology per service, and smaller codebases that one team fully understands.
3. **What are the disadvantages?**
   Network latency and partial failure, no cross-service ACID transactions, harder testing and debugging, data duplication, versioned contracts, and a large platform cost (CI/CD, monitoring, tracing, service discovery, on-call per service).

**Follow-up**
4. **What is a modular monolith and why do many teams prefer it?**
   One deployable with strong internal module boundaries: each module has a public API and private internals and owns its tables. You get most of the design benefits (clear ownership, low coupling) without network costs, and extracting a module later is easy because the boundary already exists.
5. **What is a distributed monolith and how do you recognize one?**
   Services that cannot be deployed independently: they share a database schema, need coordinated releases, or call each other synchronously in long chains. Symptoms are "we must deploy services A, B and C together" and one slow service freezing everything.
6. **How would you migrate a monolith to microservices?**
   Strangler fig: put a gateway in front, pick a capability with a clear boundary and few dependencies (notifications is a classic first one), build it as a service with its own data, route its traffic to the new service, sync data during transition, then delete the old code. One capability at a time, never a rewrite.

**Tricky / scenario**
7. **A startup with five developers wants microservices "to be scalable". What do you say?**
   I would push back. Five developers cannot run ten services with on-call, tracing and pipelines without slowing feature work to a crawl. A modular monolith scales horizontally fine behind a load balancer; extract services later when a real pressure appears. Conway's law says the architecture should follow team structure, and one team means one deployable.
8. **After splitting, checkout p99 latency doubled. Why, and what do you do?**
   Every synchronous hop adds network time, serialization and its own tail latency, and tails compound (the slowest of several calls dominates). Fixes: remove chatty calls (fetch in batches, cache reference data locally), turn non-critical steps (notifications, analytics) into async events, call independent services in parallel, and set strict timeouts.
9. **Two services share one database "temporarily". What is the risk?**
   Schema changes by one team break the other, you cannot deploy or scale them independently, and nobody owns the data. It is acceptable only as a short migration step with separate schemas and a plan to split. Long-term, each service owns its data and others access it via API or events.

**What the interviewer is really testing:** whether you treat microservices as a trade-off with real costs instead of a default, and whether you can name the concrete pressures that justify splitting.

## 5. Pitfalls & Best Practices
### Common mistakes
| Mistake | What goes wrong | Fix |
|---|---|---|
| Splitting by technical layer (UI service, DB service) | Every feature touches every service | Split by business capability |
| Shared database between services | Hidden coupling, coordinated deploys | Database per service, integrate via API or events |
| Long synchronous call chains | Latency and failures multiply | Async events, parallel calls, aggregate data |
| Starting with microservices on day one | Wrong boundaries frozen into network contracts | Modular monolith first, extract later |
| No platform (tracing, central logs, CI/CD) | Cannot debug or ship | Build observability and pipelines before splitting |
| Nano-services (one per entity) | Chatty, fragile system | Services sized to a bounded context and a team |

### Best practices
- Write down the reason for each extraction (an ADR): which pressure, which metric will prove it worked.
- Keep services independently deployable: backward-compatible APIs, versioned events, consumer-driven contract tests.
- Prefer asynchronous events for anything the user does not need to wait for.
- Give every service a clear owner team, its own pipeline and its own dashboards.
- Enforce modular boundaries inside the monolith first (Spring Modulith `ApplicationModules.of(App.class).verify()` in a test).

### Compare with
| Style | Deployables | Data | When |
|---|---|---|---|
| Classic monolith | 1 | Shared schema, no boundaries | Prototypes, tiny apps |
| Modular monolith | 1 | Tables owned per module | Default for most teams |
| Microservices | Many | Database per service | Many teams, clear contexts, strong platform |
| Serverless functions | Many tiny | Managed stores | Spiky, event-driven workloads |

## 6. Hands-on Exercise
OrderHub is still one application with packages `product`, `order`, `inventory` and `notification`. Prepare it for extraction without adding any network calls:
1. Make each package a module with a public API class (for example `InventoryApi`) and keep everything else package-private.
2. Replace the direct call from `OrderService` to `NotificationService` with a Spring application event `OrderPlacedEvent`.
3. Add a test that fails if one module reaches into another module's internals.

Acceptance criteria: `OrderService` no longer imports anything from `notification`; the module test passes; placing an order still sends the notification.

<details><summary>Solution</summary>

```xml
<!-- pom.xml -->
<dependency>
    <groupId>org.springframework.modulith</groupId>
    <artifactId>spring-modulith-starter-core</artifactId>
</dependency>
<dependency>
    <groupId>org.springframework.modulith</groupId>
    <artifactId>spring-modulith-starter-test</artifactId>
    <scope>test</scope>
</dependency>
<!-- in dependencyManagement: org.springframework.modulith:spring-modulith-bom:1.4.1, type pom, scope import -->
```

```java
// order/OrderPlacedEvent.java (public: part of the order module's API)
package com.orderhub.order;

import java.math.BigDecimal;

public record OrderPlacedEvent(long orderId, long customerId, BigDecimal total) { }
```

```java
// order/OrderService.java
package com.orderhub.order;

import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {
    private final OrderRepository orders;
    private final ApplicationEventPublisher events;

    public OrderService(OrderRepository orders, ApplicationEventPublisher events) {
        this.orders = orders;
        this.events = events;
    }

    @Transactional
    public Order place(PlaceOrderCommand cmd) {
        Order order = orders.save(Order.newOrder(cmd));
        events.publishEvent(new OrderPlacedEvent(order.getId(), cmd.customerId(), order.getTotal()));
        return order;
    }
}
```

```java
// notification/NotificationListener.java (package-private internals)
package com.orderhub.notification;

import com.orderhub.order.OrderPlacedEvent;
import org.springframework.modulith.events.ApplicationModuleListener;
import org.springframework.stereotype.Component;

@Component
class NotificationListener {
    private final EmailSender email;

    NotificationListener(EmailSender email) { this.email = email; }

    // Runs after the order transaction commits, asynchronously, in its own transaction
    @ApplicationModuleListener
    void on(OrderPlacedEvent event) {
        email.send(event.customerId(), "Order " + event.orderId() + " confirmed");
    }
}
```

```java
// src/test/java/com/orderhub/ModularityTest.java
package com.orderhub;

import org.junit.jupiter.api.Test;
import org.springframework.modulith.core.ApplicationModules;

class ModularityTest {
    @Test
    void modulesRespectBoundaries() {
        ApplicationModules.of(OrderHubApplication.class).verify();   // fails on illegal cross-module access
    }
}
```

The event is the seam: later, when notification becomes its own service, the same `OrderPlacedEvent` is published to Kafka instead of in-process, and `OrderService` barely changes.
</details>

## 7. Recall
Q: What is the main trade-off of microservices versus a monolith?
A: Independent deployment, scaling and team autonomy in exchange for network failures, eventual consistency, harder debugging and much higher operational cost.

Q: What is a modular monolith?
A: One deployable application split internally into modules with strict public APIs and owned data, so it can be split later cheaply.

Q: What is a distributed monolith in microservices architecture?
A: Services that share a database or must be deployed together, so they have the costs of distribution without independent deployability.

Q: Why does a chain of five 99.9% available services give lower availability?
A: Every hop must succeed, so availabilities multiply: 0.999 to the power 5 is about 99.5%, five times the downtime.

Q: What is the strangler fig pattern for migrating a monolith?
A: Route one capability at a time from the monolith to a new service behind a gateway until the old code can be deleted, instead of a big-bang rewrite.

**Related:** [[Service Decomposition and DDD Basics]] · [[API Gateway with Spring Cloud Gateway]] · [[Distributed Transactions, Saga and Outbox]]

# Service Decomposition and DDD Basics

**Level: Advanced | Phase 20 | Priority: SHOULD | Since: Domain-Driven Design (Eric Evans, 2003)**

> **30-second interview answer:** I draw service boundaries around business capabilities using Domain-Driven Design: a bounded context is a part of the domain where each word has one precise meaning, and it is the natural candidate for a service. Inside a context, aggregates are clusters of objects that must stay consistent together and are changed in one transaction. Contexts talk through APIs or domain events and translate each other's models, so "Product" in Catalog can differ from "StockItem" in Inventory without either team breaking the other.

## 1. Concept in Simple Words
### Analogy
A hospital's departments.

| Hospital | DDD |
|---|---|
| The word "patient" means a bed and chart to a ward, an invoice to billing, a sample to the lab | The same term has different models in different bounded contexts |
| Each department has its own forms and records | Each context owns its own model and database |
| Shared jargon inside a department ("obs", "NBM") | Ubiquitous language |
| A transfer form between ward and billing | Published contract (API or domain event) |
| The receptionist who rewrites a referral into the hospital's own format | Anti-corruption layer |
| One patient chart with its medication list: always updated together | Aggregate with an aggregate root |
| "Patient discharged" announcement | Domain event |

### What it is
- **Domain:** the business area the software serves (online ordering).
- **Subdomain:** a part of it. **Core** (your competitive edge, e.g. pricing), **supporting** (needed but specific, e.g. inventory), **generic** (solved problems, e.g. email sending: buy or use a library).
- **Bounded context:** an explicit boundary inside which a model and its language are consistent. A good first guess for a service boundary.
- **Ubiquitous language:** the shared vocabulary of developers and domain experts within one context, used in code (class names, method names).
- **Entity:** an object with identity that persists over time (`Order` with id 42). **Value object:** defined only by its values and immutable (`Money`, `Address`); Java records fit perfectly.
- **Aggregate:** a cluster of entities and value objects treated as one unit for changes. The **aggregate root** (`Order`) is the only entry point; outside code never edits an `OrderLine` directly. One transaction changes one aggregate.
- **Domain event:** a record of something that happened in the domain, named in the past tense (`OrderPlaced`).
- **Context map:** how contexts relate: customer-supplier, conformist, shared kernel, or anti-corruption layer (ACL), a translation layer that protects your model from another context's model.

### Why it exists
Without explicit boundaries, one giant `Product` class grows fields for catalog, pricing, stock, shipping and tax, and every team edits it. Splitting such a system into services by entity ("product-service", "customer-service") produces chatty services that all need each other for every request. DDD gives a method to find seams where the language and the rules change, which are also the places with the least traffic across the boundary.

## 2. How It Works
Steps to decompose OrderHub:

```mermaid
flowchart TD
    A["Event storming: list domain events on a timeline"] --> B["Group events by who owns the decision"]
    B --> C["Name bounded contexts and their language"]
    C --> D["Find aggregates and their invariants"]
    D --> E["Draw the context map: who depends on whom"]
    E --> F["Pick services: one context per service, or several small contexts per service"]
```

Event storming for OrderHub gives this timeline: `ProductListed`, `PriceChanged`, `OrderPlaced`, `StockReserved` or `StockRejected`, `PaymentCaptured`, `OrderConfirmed`, `OrderShipped`, `CustomerNotified`. Grouping by owner:

```text
+-------------------+   +----------------------+   +----------------------+
| Catalog context   |   | Ordering context     |   | Inventory context    |
| Product: name,    |   | Order (root)         |   | StockItem: sku,      |
| description,      |   |  - OrderLine (sku,   |   | onHand, reserved     |
| images, price     |   |    qty, unitPrice)   |   | Reservation(orderId) |
|                   |   |  - status, total     |   |                      |
| events:           |   | events: OrderPlaced, |   | events:              |
|  PriceChanged     |   |  OrderConfirmed      |   |  StockReserved       |
+---------+---------+   +----------+-----------+   |  StockRejected       |
          | price snapshot          | OrderPlaced  +----------+-----------+
          +-----------> Ordering <--+--------------> Inventory |
                                    v                           |
                         +----------------------+               |
                         | Notification context |<--------------+
                         | (generic subdomain)  |
                         +----------------------+
```

Rules of thumb for good boundaries:
- **High cohesion inside, low traffic across:** if two candidate services need to call each other for almost every request, they belong together.
- **One aggregate per transaction:** if a business rule needs two aggregates updated atomically, either they are one aggregate or the rule can be eventually consistent.
- **Copy, do not share:** Ordering keeps a snapshot of the price at order time instead of calling Catalog every time it shows an old order.
- **Size by team:** one team can own several contexts, but one context should not be split across teams.

## 3. Code Example
### Code
A plain Java 21 program showing two bounded contexts with their own models, an aggregate root that guards invariants and records a domain event, and an anti-corruption layer translating between contexts.

```java
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class BoundedContextsDemo {

    // ===== Ordering context =====
    record Money(BigDecimal amount) {                       // value object
        Money {
            if (amount.signum() < 0) throw new IllegalArgumentException("negative money");
        }
        Money times(int qty) { return new Money(amount.multiply(BigDecimal.valueOf(qty))); }
        Money plus(Money other) { return new Money(amount.add(other.amount)); }
        static Money zero() { return new Money(BigDecimal.ZERO); }
    }

    record OrderLine(String sku, int quantity, Money unitPrice) { }    // part of the aggregate

    record OrderPlaced(long orderId, List<OrderLine> lines, Money total) { }   // domain event

    enum OrderStatus { DRAFT, PLACED, CONFIRMED, REJECTED }

    static final class Order {                              // aggregate root
        private final long id;
        private final List<OrderLine> lines = new ArrayList<>();
        private OrderStatus status = OrderStatus.DRAFT;
        private final List<Object> pendingEvents = new ArrayList<>();
        private static final int MAX_LINES = 20;

        Order(long id) { this.id = id; }

        void addLine(String sku, int qty, Money unitPrice) {
            if (status != OrderStatus.DRAFT) throw new IllegalStateException("order is " + status);
            if (qty <= 0) throw new IllegalArgumentException("quantity must be positive");
            if (lines.size() == MAX_LINES) throw new IllegalStateException("too many lines");
            lines.add(new OrderLine(sku, qty, unitPrice));
        }

        void place() {
            if (lines.isEmpty()) throw new IllegalStateException("cannot place an empty order");
            status = OrderStatus.PLACED;
            pendingEvents.add(new OrderPlaced(id, List.copyOf(lines), total()));
        }

        void confirm() { requireStatus(OrderStatus.PLACED); status = OrderStatus.CONFIRMED; }
        void reject()  { requireStatus(OrderStatus.PLACED); status = OrderStatus.REJECTED; }

        private void requireStatus(OrderStatus expected) {
            if (status != expected) throw new IllegalStateException("expected " + expected + " but was " + status);
        }

        Money total() {
            Money sum = Money.zero();
            for (OrderLine l : lines) sum = sum.plus(l.unitPrice().times(l.quantity()));
            return sum;
        }

        List<Object> pullEvents() {                         // events leave the aggregate once
            List<Object> copy = List.copyOf(pendingEvents);
            pendingEvents.clear();
            return copy;
        }

        OrderStatus status() { return status; }
    }

    // ===== Inventory context: its own model and language =====
    record ReserveStock(String reference, Map<String, Integer> quantitiesBySku) { }

    static final class StockLedger {
        private final Map<String, Integer> available = new HashMap<>();

        void receive(String sku, int qty) { available.merge(sku, qty, Integer::sum); }

        boolean tryReserve(ReserveStock cmd) {
            for (var e : cmd.quantitiesBySku().entrySet()) {
                if (available.getOrDefault(e.getKey(), 0) < e.getValue()) return false;
            }
            cmd.quantitiesBySku().forEach((sku, qty) -> available.merge(sku, -qty, Integer::sum));
            return true;
        }

        int available(String sku) { return available.getOrDefault(sku, 0); }
    }

    // ===== Anti-corruption layer: Ordering event -> Inventory command =====
    static ReserveStock translate(OrderPlaced event) {
        Map<String, Integer> bySku = new HashMap<>();
        for (OrderLine l : event.lines()) bySku.merge(l.sku(), l.quantity(), Integer::sum);
        return new ReserveStock("order-" + event.orderId(), bySku);
    }

    public static void main(String[] args) {
        StockLedger ledger = new StockLedger();
        ledger.receive("BOOK-1", 5);
        ledger.receive("PEN-9", 1);

        Order first = new Order(42);
        first.addLine("BOOK-1", 2, new Money(new BigDecimal("12.50")));
        first.addLine("BOOK-1", 1, new Money(new BigDecimal("12.50")));
        first.place();
        handle(first, ledger);

        Order second = new Order(43);
        second.addLine("PEN-9", 3, new Money(new BigDecimal("1.20")));
        second.place();
        handle(second, ledger);

        try {
            second.addLine("BOOK-1", 1, new Money(new BigDecimal("12.50")));
        } catch (IllegalStateException e) {
            System.out.println("invariant protected: " + e.getMessage());
        }
        System.out.println("BOOK-1 left: " + ledger.available("BOOK-1") + ", PEN-9 left: " + ledger.available("PEN-9"));
    }

    static void handle(Order order, StockLedger ledger) {
        for (Object event : order.pullEvents()) {
            if (event instanceof OrderPlaced placed) {
                ReserveStock cmd = translate(placed);
                boolean ok = ledger.tryReserve(cmd);
                if (ok) order.confirm(); else order.reject();
                System.out.println(cmd.reference() + " total " + placed.total().amount()
                        + " reserve " + cmd.quantitiesBySku() + " -> " + order.status());
            }
        }
    }
}
```

### Walkthrough
- `Money` is a value object: a record with validation in its compact constructor. Two `Money` objects with the same amount are interchangeable.
- `Order` is the aggregate root. `OrderLine` objects can only be added through `addLine`, which checks status, quantity and the maximum line count. Nobody outside can put the order in an invalid state.
- `place()` records an `OrderPlaced` domain event instead of calling inventory directly. The aggregate does not know who listens; in a Spring service the events are published after the transaction commits.
- Inventory has its own language: it does not know "orders" or "lines", only a `ReserveStock` command with a reference and quantities per SKU.
- `translate` is the anti-corruption layer. It merges the two `BOOK-1` lines into one quantity of 3. If Ordering renames a field tomorrow, only this translator changes.
- Order 43 asks for 3 pens when only 1 exists, so the reservation fails and the order is rejected; afterwards `addLine` is refused because the order is no longer a draft.

### Output
```text
order-42 total 37.50 reserve {BOOK-1=3} -> CONFIRMED
order-43 total 3.60 reserve {PEN-9=3} -> REJECTED
invariant protected: order is REJECTED
BOOK-1 left: 2, PEN-9 left: 1
```

### Compare
| Decomposition by entity (anti-pattern) | Decomposition by bounded context |
|---|---|
| product-service, customer-service, order-service, line-service | catalog, ordering, inventory, notification |
| Every request calls three or four services | Most requests stay inside one service |
| One shared `Product` model for everyone | Each context has its own model of a product |
| CRUD APIs, logic leaks into callers | Behaviour APIs (`place`, `reserve`) and events |

## 4. Interview Questions
**Basic**
1. **What is a bounded context?**
   An explicit boundary inside which a domain model and its terms have one consistent meaning. "Product" in Catalog (descriptions, images) and in Inventory (SKU, quantity on hand) are different models in different contexts. A bounded context is usually the best first candidate for a microservice.
2. **What is an aggregate?**
   A cluster of domain objects that must stay consistent together, changed only through its root. The rule is one aggregate per transaction, and other aggregates are referenced by id, not by object reference.
3. **Entity vs value object?**
   An entity has identity that survives changes (`Customer` 7 stays customer 7 after changing address). A value object is defined only by its values and is immutable (`Money`, `Address`). Records are a natural fit for value objects.

**Follow-up**
4. **How do you find service boundaries in practice?**
   Run event storming with domain experts, group events by the part of the business that owns the decision, look for where language changes, and check traffic: if two candidates must talk on every request, merge them. Align the result with team ownership (Conway's law).
5. **What is an anti-corruption layer and when do you need one?**
   A translation layer between your model and another context's or legacy system's model, so foreign concepts do not leak into your code. You need it when integrating with a legacy system or a context whose model you do not control.
6. **Why should aggregates be small?**
   Large aggregates mean big transactions, lock contention and loading too much data. Small aggregates with references by id scale better, and cross-aggregate rules become eventually consistent through domain events.

**Tricky / scenario**
7. **The business says "an order must never be placed if stock is unavailable". Inventory is another service. How do you honour that?**
   Ask how strict the rule really is. Usually "pending until stock is reserved" is acceptable: the order is created as PENDING, an event triggers reservation, and the order moves to CONFIRMED or REJECTED (a saga). If it must be synchronous, call inventory to reserve first with a timeout and idempotency key, then compensate (release) if the order save fails.
8. **Your team split by entity and now order-service calls customer-service, product-service and price-service on every request. What do you do?**
   That is a sign of wrong boundaries. Short term: cache reference data or replicate it via events into order-service (a local read model). Long term: merge services that change together into one bounded context and keep only real business seams as service boundaries.
9. **Can one bounded context span multiple microservices, or one microservice contain several contexts?**
   A service may contain several small related contexts when one team owns them, which is common and fine. Splitting one context across services is a smell because its model must stay consistent, which forces distributed transactions or tight coupling.

**What the interviewer is really testing:** whether you can draw boundaries from the business domain instead of from database tables, and whether you understand consistency rules inside versus across boundaries.

## 5. Pitfalls & Best Practices
### Common mistakes
| Mistake | What goes wrong | Fix |
|---|---|---|
| One service per database table | Chatty calls, no cohesion | Service per bounded context |
| One shared domain library for all services | Every change forces all services to redeploy | Each service owns its model; share only contracts |
| Huge aggregates (customer with all orders) | Slow loads, lock contention | Small aggregates, references by id |
| Updating two aggregates in one transaction across services | Needs 2PC, fragile | Domain events and sagas |
| Leaking another context's model into yours | Their change breaks you | Anti-corruption layer, translate at the edge |

### Best practices
- Name code in the ubiquitous language: `order.place()`, not `orderDao.updateStatus(2)`.
- Model value objects as records with validation in the compact constructor.
- Publish domain events in the past tense and keep them as stable contracts (version them).
- Store snapshots of data you need from other contexts (price at order time, customer name on the invoice).
- Start with coarse services and split later; merging services is much harder than splitting modules.

### Compare with
| Context map relation | Meaning | Example |
|---|---|---|
| Customer-supplier | Downstream needs are negotiated with upstream | Ordering asks Catalog for price snapshots |
| Conformist | Downstream accepts upstream model as is | Using a payment provider's API model |
| Anti-corruption layer | Downstream translates upstream model | Inventory translating `OrderPlaced` into `ReserveStock` |
| Shared kernel | Two contexts share a small common model | A shared `Money` contract library |
| Published language | A documented exchange format | Versioned JSON or Avro event schemas |

## 6. Hands-on Exercise
Model the OrderHub Inventory context for the upcoming inventory-service:
- `StockItem` aggregate root with `sku`, `onHand`, and a list of `Reservation(orderId, quantity)`.
- `reserve(orderId, qty)`: fails with `InsufficientStockException` if `onHand - reserved < qty`; reserving twice for the same order is a no-op (idempotent).
- `release(orderId)`: removes the reservation (compensation).
- `available()` returns `onHand` minus all reserved quantities.

Acceptance criteria: invariants hold under the calls `reserve(1,3)`, `reserve(1,3)` again, `reserve(2,5)` (fails with onHand 7), `release(1)`, `reserve(2,5)` (succeeds).

<details><summary>Solution</summary>

```java
import java.util.ArrayList;
import java.util.List;

public class StockItem {
    record Reservation(long orderId, int quantity) { }

    static class InsufficientStockException extends RuntimeException {
        InsufficientStockException(String sku, int wanted, int available) {
            super("sku " + sku + ": wanted " + wanted + ", available " + available);
        }
    }

    private final String sku;
    private int onHand;
    private final List<Reservation> reservations = new ArrayList<>();

    public StockItem(String sku, int onHand) {
        if (onHand < 0) throw new IllegalArgumentException("onHand must be >= 0");
        this.sku = sku;
        this.onHand = onHand;
    }

    public void reserve(long orderId, int qty) {
        if (qty <= 0) throw new IllegalArgumentException("qty must be positive");
        boolean already = reservations.stream().anyMatch(r -> r.orderId() == orderId);
        if (already) return;                                  // idempotent: retries are safe
        if (available() < qty) throw new InsufficientStockException(sku, qty, available());
        reservations.add(new Reservation(orderId, qty));
    }

    public void release(long orderId) {
        reservations.removeIf(r -> r.orderId() == orderId);   // compensation, also idempotent
    }

    public int available() {
        return onHand - reservations.stream().mapToInt(Reservation::quantity).sum();
    }

    public static void main(String[] args) {
        StockItem book = new StockItem("BOOK-1", 7);
        book.reserve(1, 3);
        book.reserve(1, 3);                                   // duplicate message: ignored
        System.out.println("after order 1: " + book.available());
        try {
            book.reserve(2, 5);
        } catch (InsufficientStockException e) {
            System.out.println("rejected: " + e.getMessage());
        }
        book.release(1);
        book.reserve(2, 5);
        System.out.println("after release and order 2: " + book.available());
    }
}
```
Output:
```text
after order 1: 4
rejected: sku BOOK-1: wanted 5, available 4
after release and order 2: 2
```
Idempotent `reserve` and `release` matter because messages and HTTP retries can be delivered twice in a distributed system.
</details>

## 7. Recall
Q: What is a bounded context in DDD?
A: An explicit boundary inside which a model and its terms have one consistent meaning; it is the usual candidate for a microservice boundary.

Q: What is an aggregate root in DDD?
A: The single entry point of a cluster of objects that must stay consistent; all changes go through it, and one transaction changes one aggregate.

Q: What is an anti-corruption layer?
A: A translation layer that converts another context's or legacy system's model into your own, so foreign concepts do not leak into your code.

Q: Why is decomposing microservices by database entity an anti-pattern?
A: Every use case then needs several services, causing chatty calls, shared models and coordinated deployments.

Q: How should a service get data it needs from another bounded context?
A: Through an API or by keeping a local copy fed by domain events (for example a price snapshot), never by reading the other service's database.

**Related:** [[Monolith vs Microservices]] · [[Distributed Transactions, Saga and Outbox]] · [[Event-Driven Architecture with Kafka]]

# Service Discovery

**Level: Advanced | Phase 20 | Priority: MUST | Since: Netflix Eureka in Spring Cloud (2015); Spring Cloud LoadBalancer replaced Ribbon in 2020.0**

> **30-second interview answer:** Service discovery lets services find each other by name instead of hard-coded addresses, because instances come and go with scaling and deployments. Each instance registers with a registry (Eureka) and renews a lease with heartbeats; callers fetch the registry and pick an instance with client-side load balancing (Spring Cloud LoadBalancer, used by `lb://` URIs and `@LoadBalanced` clients). On Kubernetes you usually skip Eureka: a Service gives a stable DNS name and kube-proxy load-balances for you.

## 1. Concept in Simple Words
### Analogy
A taxi company's dispatch board.

| Taxi dispatch | Service discovery |
|---|---|
| Each driver radios in "car 12 is on duty at Main Street" | Instance registers host, port and status |
| Driver checks in every few minutes or is removed | Heartbeat renews the lease; expired leases are evicted |
| The dispatch board listing all cars on duty | Service registry (Eureka server) |
| The dispatcher picks the next free car | Client-side load balancer picks an instance |
| Customers call "City Taxi", not a specific driver's phone | Callers use a logical name `inventory-service` |
| Each customer keeps a printed copy of the board for a while | Client caches the registry and refreshes every 30 s |

### What it is
- **Service registry:** a database of available instances per service name. Eureka (Netflix, in Spring Cloud), Consul, ZooKeeper, or Kubernetes' own API.
- **Registration:** on startup a service tells the registry "I am `inventory-service` at 10.0.1.9:8082". **Self-registration** (the app does it, Eureka client) or **third-party registration** (the platform does it, Kubernetes).
- **Heartbeat / lease renewal:** the instance pings the registry periodically (Eureka: every 30 s); without renewals the lease expires (90 s) and the instance is evicted.
- **Client-side discovery:** the caller fetches the instance list and chooses one itself (Eureka + Spring Cloud LoadBalancer).
- **Server-side discovery:** the caller hits a stable address and an infrastructure load balancer chooses (Kubernetes Service, AWS ALB).
- **Spring Cloud LoadBalancer:** the client-side load balancer in Spring Cloud; round robin by default, random or custom available.

### Why it exists
In a cloud or container environment, instances get new IP addresses on every restart and their number changes with autoscaling. A hard-coded `http://10.0.1.9:8082` in configuration breaks on the next deployment. Discovery turns "where is it?" into a runtime lookup by name.

## 2. How It Works
```mermaid
sequenceDiagram
    participant I1 as "inventory-service 1"
    participant I2 as "inventory-service 2"
    participant E as "Eureka server"
    participant O as "order-service"
    I1->>E: "POST /eureka/apps/INVENTORY-SERVICE (register)"
    I2->>E: "POST register"
    loop "every 30 s"
        I1->>E: "PUT heartbeat (renew lease)"
        I2->>E: "PUT heartbeat"
    end
    O->>E: "GET /eureka/apps/delta (every 30 s)"
    E-->>O: "INVENTORY-SERVICE: [10.0.1.9:8082, 10.0.1.12:8082]"
    O->>O: "LoadBalancer picks instance 2 (round robin)"
    O->>I2: "POST /api/inventory/reservations"
```

Timing facts that explain production surprises:
- A new instance can take up to about a minute to receive traffic: registration, then the server's response cache (30 s), then the client's registry refresh (30 s), then the load balancer's cache.
- A killed instance (no graceful deregistration) keeps receiving traffic until its lease expires (90 s) and clients refresh. That is why callers need retries to another instance and why graceful shutdown deregisters first.
- **Self-preservation mode:** if Eureka suddenly loses many heartbeats (more than 15% below expected), it assumes a network partition and stops evicting, preferring stale entries over deleting healthy ones. You see "EMERGENCY! EUREKA MAY BE INCORRECTLY CLAIMING INSTANCES ARE UP" on the dashboard.
- Eureka favours availability over consistency (AP in CAP terms): clients keep working with their cached copy even if the Eureka server is down.

```text
Kubernetes alternative (server-side discovery)
order-service pod --> http://inventory-service:8082   (DNS name of a K8s Service)
                          |
                    kube-proxy / iptables picks a READY pod
                          |
          +---------------+---------------+
          v                               v
   inventory pod A (ready)         inventory pod B (ready)
Readiness probes decide which pods receive traffic; no Eureka client needed.
```

## 3. Code Example
### Code
Eureka server, an inventory instance that registers, and order-service calling it by name.

```xml
<!-- discovery-server/pom.xml (Spring Cloud BOM 2025.0.0 imported as in the gateway) -->
<dependency>
    <groupId>org.springframework.cloud</groupId>
    <artifactId>spring-cloud-starter-netflix-eureka-server</artifactId>
</dependency>

<!-- inventory-service/pom.xml and order-service/pom.xml -->
<dependency>
    <groupId>org.springframework.cloud</groupId>
    <artifactId>spring-cloud-starter-netflix-eureka-client</artifactId>
</dependency>
<!-- eureka-client brings spring-cloud-starter-loadbalancer transitively -->
```

```java
// discovery-server/src/main/java/com/orderhub/discovery/DiscoveryServerApplication.java
package com.orderhub.discovery;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.netflix.eureka.server.EnableEurekaServer;

@SpringBootApplication
@EnableEurekaServer
public class DiscoveryServerApplication {
    public static void main(String[] args) {
        SpringApplication.run(DiscoveryServerApplication.class, args);
    }
}
```

```yaml
# discovery-server/src/main/resources/application.yml
server:
  port: 8761
spring:
  application:
    name: discovery-server
eureka:
  client:
    register-with-eureka: false   # the server does not register with itself
    fetch-registry: false
  server:
    enable-self-preservation: true
```

```yaml
# inventory-service/src/main/resources/application.yml
server:
  port: ${PORT:8082}              # start a second instance with PORT=8092
spring:
  application:
    name: inventory-service       # this IS the service id in the registry
eureka:
  client:
    service-url:
      defaultZone: http://localhost:8761/eureka/
    registry-fetch-interval-seconds: 10     # default 30; lower = faster discovery, more load
  instance:
    prefer-ip-address: true
    lease-renewal-interval-in-seconds: 10   # default 30
    lease-expiration-duration-in-seconds: 30 # default 90
```

```java
// inventory-service: an endpoint that reveals which instance answered
package com.orderhub.inventory;

import java.util.Map;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
class WhoAmIController {
    @Value("${server.port}") int port;

    @GetMapping("/api/inventory/whoami")
    Map<String, Object> whoami() {
        return Map.of("service", "inventory-service", "port", port);
    }
}
```

```java
// order-service/src/main/java/com/orderhub/order/client/ClientConfig.java
package com.orderhub.order.client;

import org.springframework.cloud.client.loadbalancer.LoadBalanced;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

@Configuration
class ClientConfig {

    @Bean
    @LoadBalanced                       // adds an interceptor that resolves service names
    RestClient.Builder loadBalancedRestClientBuilder() {
        return RestClient.builder();
    }
}
```

```java
// order-service/src/main/java/com/orderhub/order/client/DiscoveryDemoController.java
package com.orderhub.order.client;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.springframework.cloud.client.ServiceInstance;
import org.springframework.cloud.client.discovery.DiscoveryClient;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.RestClient;

@RestController
class DiscoveryDemoController {
    private final DiscoveryClient discovery;
    private final RestClient inventory;

    DiscoveryDemoController(DiscoveryClient discovery, RestClient.Builder lbBuilder) {
        this.discovery = discovery;
        this.inventory = lbBuilder.baseUrl("http://inventory-service").build();  // logical name
    }

    @GetMapping("/api/debug/instances")
    List<String> instances() {
        return discovery.getInstances("inventory-service").stream()
                .map(ServiceInstance::getUri)
                .map(Object::toString)
                .toList();
    }

    @GetMapping("/api/debug/round-robin")
    List<Object> roundRobin() {
        List<Object> ports = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            Map<?, ?> body = inventory.get().uri("/api/inventory/whoami").retrieve().body(Map.class);
            ports.add(body.get("port"));
        }
        return ports;
    }
}
```

### Walkthrough
- `@EnableEurekaServer` turns a Boot app into the registry with a dashboard at `http://localhost:8761`. The server is told not to register with itself.
- `spring.application.name` is the service id. Two inventory instances with different ports register under the same id `INVENTORY-SERVICE` (Eureka upper-cases it).
- Shorter lease and fetch intervals make discovery faster in this demo; in production keep the defaults unless you measure a need, because they multiply registry traffic.
- `@LoadBalanced` on a `RestClient.Builder` makes Spring Cloud add `LoadBalancerInterceptor`: when the host part of a URL is `inventory-service`, it asks `ReactorLoadBalancer` for an instance and rewrites the URL to that instance's address.
- `DiscoveryClient` is the low-level API: `getInstances` returns the cached list. Useful for debugging, rarely needed in business code.
- The round-robin endpoint calls four times and shows requests alternating between the two instances.

### Output
inventory-service startup log:

```text
INFO  c.n.d.DiscoveryClient : DiscoveryClient_INVENTORY-SERVICE/192.168.1.20:inventory-service:8082: registering service...
INFO  c.n.d.DiscoveryClient : DiscoveryClient_INVENTORY-SERVICE/192.168.1.20:inventory-service:8082 - registration status: 204
```

```http
GET http://localhost:8081/api/debug/instances

HTTP/1.1 200 OK
["http://192.168.1.20:8082","http://192.168.1.20:8092"]
```

```http
GET http://localhost:8081/api/debug/round-robin

HTTP/1.1 200 OK
[8082,8092,8082,8092]
```

### Compare
| Hard-coded URL | Discovery by name |
|---|---|
| `inventory.url: http://10.0.1.9:8082` | `http://inventory-service` with `@LoadBalanced` |
| Breaks when the instance moves | Follows instances automatically |
| One instance, no load balancing | Round robin across all healthy instances |
| Scaling needs a config change | Scaling is automatic |

## 4. Interview Questions
**Basic**
1. **What is service discovery and why do microservices need it?**
   A mechanism for services to find each other's network locations by logical name. Instances are created, moved and destroyed constantly by scaling and deployments, so fixed addresses do not work.
2. **Client-side vs server-side discovery?**
   Client-side: the caller gets the instance list from the registry and chooses (Eureka + Spring Cloud LoadBalancer). Server-side: the caller calls a stable address and infrastructure chooses (Kubernetes Service, cloud load balancer). Client-side gives smarter routing; server-side keeps clients simpler and language-agnostic.
3. **What does `@LoadBalanced` do?**
   It marks a `RestClient.Builder`, `RestTemplate` or `WebClient.Builder` so Spring Cloud adds an interceptor that resolves service names in URLs to real instances using Spring Cloud LoadBalancer.

**Follow-up**
4. **How does Eureka know an instance is dead?**
   Instances renew their lease every 30 seconds; if no renewal arrives for 90 seconds, the server evicts the instance (unless in self-preservation mode). Graceful shutdown sends an explicit cancel so removal is immediate.
5. **What is Eureka self-preservation?**
   When renewals drop sharply, Eureka assumes the problem is the network, not the instances, and stops evicting entries. It avoids wiping the registry during a partition at the cost of possibly returning dead instances, so clients need retries.
6. **Do you need Eureka on Kubernetes?**
   Usually not. Kubernetes Services give stable DNS names and route only to pods that pass readiness probes. Spring Cloud Kubernetes can expose K8s services through `DiscoveryClient` if you want `lb://` semantics, but most teams just use the DNS name.

**Tricky / scenario**
7. **After a deployment, some requests fail for about a minute with connection refused. Why?**
   Old instances were killed before clients' cached registries noticed: Eureka server caches, client refresh intervals and LoadBalancer caches all add delay. Fix with graceful shutdown (deregister, wait, then stop), retries on another instance for idempotent calls, and readiness-based traffic shifting.
8. **The Eureka server goes down. Does order-service stop working?**
   No. Clients keep their last fetched registry and keep calling known instances. New instances will not be discovered and dead ones not removed until Eureka is back, so run at least two Eureka peers in production.
9. **A new instance of inventory gets 3x more traffic than the others right after startup and its latency spikes. What can help?**
   JIT warm-up makes a cold JVM slow; with round robin it still gets an equal share. Options: warm up before reporting ready (readiness probe after a warm-up routine), use a weighted or least-load strategy, or CDS/AOT to start faster. Also check that the cold pool (connections, caches) is not the bottleneck.

**What the interviewer is really testing:** whether you understand registration, leases and caching delays, and can explain discovery both with Eureka and on Kubernetes.

## 5. Pitfalls & Best Practices
### Common mistakes
| Mistake | What goes wrong | Fix |
|---|---|---|
| Hard-coding instance IPs | Breaks on redeploy and scaling | Logical names with discovery |
| Single Eureka server in production | No new registrations during outage | Two or three peer-replicated servers |
| Forgetting `@LoadBalanced` | `UnknownHostException: inventory-service` | Annotate the client builder bean |
| Running Eureka on Kubernetes without need | Two discovery systems disagree | Use K8s Services, drop Eureka |
| Killing instances without graceful shutdown | Traffic to dead instances for up to 90 s | Graceful shutdown and deregistration |

### Best practices
- Treat discovery data as eventually consistent: always combine with timeouts and retries to a different instance.
- Prefer `prefer-ip-address: true` in containers where host names are not resolvable.
- Expose health checks and let the registry or platform use them (Eureka can use `eureka.client.healthcheck.enabled=true` to publish actuator health).
- On Kubernetes, rely on readiness probes and Services; keep the application free of registry clients.

### Compare with
| Registry | Model | Notes |
|---|---|---|
| Eureka | AP, client-side, self-registration | Simple, Spring-native, Java-centric |
| Consul | CP (Raft), health checks, KV store | Multi-language, also does config |
| ZooKeeper | CP, ephemeral nodes | Heavy; used by older Kafka and Hadoop |
| Kubernetes Services and DNS | Platform-managed, server-side | Default on K8s, no app code |
| Service mesh (Istio, Linkerd) | Sidecar proxies | mTLS, retries, traffic shifting outside the app |

## 6. Hands-on Exercise
Add discovery to OrderHub:
1. Create `discovery-server` on port 8761.
2. Register `order-service` and two `inventory-service` instances (8082 and 8092).
3. In order-service, replace `inventory.base-url: http://localhost:8082` with discovery and add a custom load-balancer configuration for inventory that uses `RandomLoadBalancer` instead of round robin.

Acceptance criteria: the Eureka dashboard shows two inventory instances; calls from order-service hit both; stopping one instance still lets requests succeed after at most one refresh cycle.

<details><summary>Solution</summary>

```java
// order-service: random strategy only for inventory-service
package com.orderhub.order.client;

import org.springframework.cloud.client.ServiceInstance;
import org.springframework.cloud.loadbalancer.core.RandomLoadBalancer;
import org.springframework.cloud.loadbalancer.core.ReactorLoadBalancer;
import org.springframework.cloud.loadbalancer.core.ServiceInstanceListSupplier;
import org.springframework.cloud.loadbalancer.support.LoadBalancerClientFactory;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;

// NOT annotated with @Configuration: it is loaded in a child context per service
class InventoryLoadBalancerConfig {

    @Bean
    ReactorLoadBalancer<ServiceInstance> randomLoadBalancer(Environment env,
                                                            LoadBalancerClientFactory factory) {
        String serviceId = env.getProperty(LoadBalancerClientFactory.PROPERTY_NAME);
        return new RandomLoadBalancer(
                factory.getLazyProvider(serviceId, ServiceInstanceListSupplier.class), serviceId);
    }
}
```

```java
package com.orderhub.order.client;

import org.springframework.cloud.client.loadbalancer.LoadBalanced;
import org.springframework.cloud.loadbalancer.annotation.LoadBalancerClient;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

@Configuration
@LoadBalancerClient(name = "inventory-service", configuration = InventoryLoadBalancerConfig.class)
class ClientConfig {

    @Bean
    @LoadBalanced
    RestClient.Builder loadBalancedRestClientBuilder() {
        return RestClient.builder();
    }
}
